from pathlib import Path

# storage.ts — granular items per scheduled slot + shared parser
p = Path('src/lib/storage.ts')
s = p.read_text()
old = '''  medLogTimes: Record<string, Record<string, string>>;\n  /** Optional user note attached to a concrete scheduled medication slot. */\n  medLogNotes?: Record<string, Record<string, string>>;\n'''
new = '''  medLogTimes: Record<string, Record<string, string>>;\n  /** Optional user note attached to a concrete scheduled medication slot. */\n  medLogNotes?: Record<string, Record<string, string>>;\n  /** Granular taken items for a grouped scheduled medication slot. */\n  medLogItems?: Record<string, Record<string, string[]>>;\n'''
if old not in s: raise SystemExit('storage BixboData target not found')
s = s.replace(old, new, 1)
s = s.replace('''  medLogTimes: {},\n  medLogNotes: {},\n''','''  medLogTimes: {},\n  medLogNotes: {},\n  medLogItems: {},\n''',1)
needle = '''export interface Med {\n  id: string;\n  name: string;\n  dose?: string;\n  times: string[];\n  asNeeded?: boolean;\n  color?: string;\n  note?: string;\n}\n'''
insert = needle + '''\n/** Split an existing grouped medication name into independently trackable items. */\nexport function medScheduleItems(med: Pick<Med, "name">): string[] {\n  const items = med.name.split(",").map((item) => item.trim()).filter(Boolean);\n  return items.length ? items : [med.name.trim()].filter(Boolean);\n}\n'''
if needle not in s: raise SystemExit('storage Med target not found')
s = s.replace(needle, insert, 1)
p.write_text(s)

# merge.ts — cloud sync granular items + notes instead of local-spread only
p = Path('src/lib/merge.ts')
s = p.read_text()
old = '''      medLog: mergeMedLog(effectiveLocal.medLog, remote.medLog),\n      medLogTimes: mergeMedLogTimes(effectiveLocal.medLogTimes, remote.medLogTimes),\n      medNames: mergeStringMap(effectiveLocal.medNames, remote.medNames, "medNames"),\n'''
new = '''      medLog: mergeMedLog(effectiveLocal.medLog, remote.medLog),\n      medLogTimes: mergeMedLogTimes(effectiveLocal.medLogTimes, remote.medLogTimes),\n      medLogNotes: mergeStructured("medLogNotes", effectiveLocal.medLogNotes ?? {}, remote.medLogNotes ?? {}) as BixboData["medLogNotes"],\n      medLogItems: mergeStructured("medLogItems", effectiveLocal.medLogItems ?? {}, remote.medLogItems ?? {}) as BixboData["medLogItems"],\n      medNames: mergeStringMap(effectiveLocal.medNames, remote.medNames, "medNames"),\n'''
if old not in s: raise SystemExit('merge target not found')
s = s.replace(old, new, 1)
p.write_text(s)

# LogSheet.tsx — grouped scheduled-dose picker with individual checkboxes + note
p = Path('src/components/LogSheet.tsx')
s = p.read_text()
# Add import symbol where storage imports are already present.
if 'medScheduleItems,' not in s:
    s = s.replace('''  painColor,\n''','''  painColor,\n  medScheduleItems,\n''',1)

old = '''  const taken = data.medLog[date] ?? {};\n  const takenTimes = data.medLogTimes?.[date] ?? {};\n  const medNotes = data.medLogNotes?.[date] ?? {};\n'''
new = '''  const taken = data.medLog[date] ?? {};\n  const takenTimes = data.medLogTimes?.[date] ?? {};\n  const medNotes = data.medLogNotes?.[date] ?? {};\n  const medItems = data.medLogItems?.[date] ?? {};\n  const [editingScheduledKey, setEditingScheduledKey] = useState<string | null>(null);\n'''
if old not in s: raise SystemExit('LogSheet state target not found')
s = s.replace(old,new,1)

# Replace only scheduled non-PRN row block.
old = '''                  const k = `${m.id}@${scheduledTime}`;\n                  const isTaken = !!taken[k];\n                  return (\n                    <label key={k} className="flex items-center gap-2 rounded-xl bg-surface px-2.5 py-2 ring-1 ring-border">\n                      <input type="checkbox" checked={isTaken} onChange={() => toggle(k, scheduledTime)} className="h-3.5 w-3.5 shrink-0" />\n                      <div className="min-w-0 flex-1">\n                        <p className="text-xs font-medium leading-tight">\n                          {m.name} <span className="text-[10px] font-normal text-muted-foreground">· scheduled {scheduledTime}</span>\n                        </p>\n                        {m.dose && <p className="text-[10px] leading-tight text-muted-foreground">{m.dose}</p>}\n                        {m.note && (\n                          <p className="text-[11px] text-muted-foreground">\n                            <Ico e="📝" size={13} /> <IcoText text={m.note} size={12} />\n                          </p>\n                        )}\n                      </div>\n                      {isTaken && (\n                        <Input\n                          type="time"\n                          value={takenTimes[k] ?? scheduledTime}\n                          onChange={(e) => setTakenTime(k, e.target.value)}\n                          className="h-7 w-20 px-2 text-xs"\n                          title={t("Actual time taken")}\n                        />\n                      )}\n                      <Input\n                        value={medNotes[k] ?? ""}\n                        onChange={(e) => setMedNote(k, e.target.value)}\n                        onClick={(e) => e.stopPropagation()}\n                        placeholder={t("Note (optional)")}\n                        className="h-7 min-w-0 flex-[0_1_125px] px-2 text-xs"\n                      />\n                    </label>\n                  );\n'''
new = '''                  const k = `${m.id}@${scheduledTime}`;\n                  const isTaken = !!taken[k];\n                  const items = medScheduleItems(m);\n                  const grouped = items.length > 1;\n                  const savedItems = medItems[k];\n                  const selectedItems = savedItems ?? (isTaken ? items : []);\n                  const partial = grouped && selectedItems.length > 0 && selectedItems.length < items.length;\n                  return (\n                    <div key={k} className="rounded-xl bg-surface px-2.5 py-2 ring-1 ring-border">\n                      <div className="flex items-center gap-2">\n                        {grouped ? (\n                          <button\n                            type="button"\n                            onClick={() => setEditingScheduledKey(editingScheduledKey === k ? null : k)}\n                            className={`grid h-5 w-5 shrink-0 place-items-center rounded-md border text-[10px] font-bold ${selectedItems.length ? "border-primary bg-primary text-primary-foreground" : "border-border bg-background text-muted-foreground"}`}\n                            aria-label={t("Choose taken medications")}\n                          >\n                            {selectedItems.length === items.length ? "✓" : selectedItems.length ? "–" : ""}\n                          </button>\n                        ) : (\n                          <input type="checkbox" checked={isTaken} onChange={() => toggle(k, nowHHMM())} className="h-3.5 w-3.5 shrink-0" />\n                        )}\n                        <button\n                          type="button"\n                          onClick={() => grouped && setEditingScheduledKey(editingScheduledKey === k ? null : k)}\n                          className="min-w-0 flex-1 text-left"\n                        >\n                          <p className="text-xs font-medium leading-tight">\n                            {m.name} <span className="text-[10px] font-normal text-muted-foreground">· scheduled {scheduledTime}</span>\n                          </p>\n                          {grouped && selectedItems.length > 0 && (\n                            <p className="mt-0.5 text-[10px] leading-tight text-primary">\n                              {partial ? `${t("Taken")}: ${selectedItems.join(", ")}` : t("All taken")}\n                            </p>\n                          )}\n                          {m.dose && <p className="text-[10px] leading-tight text-muted-foreground">{m.dose}</p>}\n                        </button>\n                        {isTaken && (\n                          <Input\n                            type="time"\n                            value={takenTimes[k] ?? scheduledTime}\n                            onChange={(e) => setTakenTime(k, e.target.value)}\n                            className="h-7 w-20 px-2 text-xs"\n                            title={t("Actual time taken")}\n                          />\n                        )}\n                      </div>\n                      {grouped && editingScheduledKey === k ? (\n                        <div className="mt-2 rounded-xl bg-tint/70 p-2 ring-1 ring-border/60">\n                          <p className="mb-1.5 text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">{t("What did you take?")}</p>\n                          <div className="space-y-1">\n                            {items.map((item) => {\n                              const checked = selectedItems.includes(item);\n                              return (\n                                <label key={item} className="flex items-center gap-2 rounded-lg bg-background/70 px-2 py-1.5 text-xs">\n                                  <input\n                                    type="checkbox"\n                                    checked={checked}\n                                    onChange={() => {\n                                      const next = checked ? selectedItems.filter((x) => x !== item) : [...selectedItems, item];\n                                      update((d) => {\n                                        const day = { ...(d.medLog[date] ?? {}) };\n                                        const allItems = { ...(d.medLogItems?.[date] ?? {}) };\n                                        const times = { ...(d.medLogTimes?.[date] ?? {}) };\n                                        if (next.length) {\n                                          day[k] = true;\n                                          allItems[k] = next;\n                                          if (!times[k]) times[k] = nowHHMM();\n                                        } else {\n                                          delete day[k];\n                                          delete allItems[k];\n                                          delete times[k];\n                                        }\n                                        return {\n                                          ...d,\n                                          medLog: { ...d.medLog, [date]: day },\n                                          medLogItems: { ...(d.medLogItems ?? {}), [date]: allItems },\n                                          medLogTimes: { ...(d.medLogTimes ?? {}), [date]: times },\n                                        };\n                                      });\n                                    }}\n                                    className="h-3.5 w-3.5"\n                                  />\n                                  <span>{item}</span>\n                                </label>\n                              );\n                            })}\n                          </div>\n                          <Input\n                            value={medNotes[k] ?? ""}\n                            onChange={(e) => setMedNote(k, e.target.value)}\n                            placeholder={t("Note (optional)")}\n                            className="mt-2 h-7 px-2 text-xs"\n                          />\n                          <button\n                            type="button"\n                            onClick={() => setEditingScheduledKey(null)}\n                            className="mt-2 w-full rounded-lg bg-primary px-3 py-1.5 text-xs font-semibold text-primary-foreground"\n                          >\n                            {t("Done")}\n                          </button>\n                        </div>\n                      ) : !grouped ? (\n                        <Input\n                          value={medNotes[k] ?? ""}\n                          onChange={(e) => setMedNote(k, e.target.value)}\n                          placeholder={t("Note (optional)")}\n                          className="mt-1.5 h-7 px-2 text-xs"\n                        />\n                      ) : null}\n                    </div>\n                  );\n'''
if old not in s: raise SystemExit('LogSheet scheduled row target not found')
s = s.replace(old,new,1)
p.write_text(s)

# index.tsx — show exactly which grouped items were taken / omitted in day overview
p = Path('src/routes/index.tsx')
s = p.read_text()
if 'medScheduleItems,' not in s:
    s = s.replace('''  painColor,\n''','''  painColor,\n  medScheduleItems,\n''',1)
# When unchecking a taken row, clear item-level selection too.
s = s.replace('''                        const times = { ...(d.medLogTimes?.[date] ?? {}) };\n                        delete times[x.key];\n                        return {\n                          ...d,\n                          medLog: { ...d.medLog, [date]: day },\n                          medLogTimes: { ...(d.medLogTimes ?? {}), [date]: times },\n                        };\n''','''                        const times = { ...(d.medLogTimes?.[date] ?? {}) };\n                        delete times[x.key];\n                        const items = { ...(d.medLogItems?.[date] ?? {}) };\n                        delete items[x.key];\n                        return {\n                          ...d,\n                          medLog: { ...d.medLog, [date]: day },\n                          medLogTimes: { ...(d.medLogTimes ?? {}), [date]: times },\n                          medLogItems: { ...(d.medLogItems ?? {}), [date]: items },\n                        };\n''',1)
old = '''                    {t("Taken")} · {actual ?? x.time} — {x.med.name}\n                    {x.med.dose ? ` (${x.med.dose})` : ""}\n                    {shifted && <span className="text-[10px] text-muted-foreground"> · {t("scheduled")} {x.time}</span>}\n                    <span className="text-[10px] text-muted-foreground"> · {t("tap to uncheck")}</span>\n'''
new = '''                    {(() => {\n                      const all = medScheduleItems(x.med);\n                      const selected = data.medLogItems?.[date]?.[x.key] ?? all;\n                      const omitted = all.filter((item) => !selected.includes(item));\n                      return (\n                        <>\n                          {t("Taken")} · {actual ?? x.time} — {selected.join(", ")}\n                          {x.med.dose ? ` (${x.med.dose})` : ""}\n                          {shifted && <span className="text-[10px] text-muted-foreground"> · {t("scheduled")} {x.time}</span>}\n                          {omitted.length ? <span className="block text-[10px] text-destructive">{t("Not taken")}: {omitted.join(", ")}</span> : null}\n                          {data.medLogNotes?.[date]?.[x.key] ? <span className="block text-[10px] text-muted-foreground">{t("Note")}: {data.medLogNotes?.[date]?.[x.key]}</span> : null}\n                          <span className="text-[10px] text-muted-foreground"> · {t("tap to uncheck")}</span>\n                        </>\n                      );\n                    })()}\n'''
if old not in s: raise SystemExit('index taken row target not found')
s = s.replace(old,new,1)
p.write_text(s)
